function clone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== "object") return value;
  if (seen.has(value)) return seen.get(value);

  const copy = Array.isArray(value) ? [] : {};
  seen.set(value, copy);
  for (const key of Object.keys(value)) copy[key] = clone(value[key], seen);
  return copy;
}

const tags = ["new"];
const post = { tags, meta: { tags }, when: new Date(0), show() {} };
const copy = clone(post);

console.log(copy.meta.tags === copy.tags, copy.tags === tags);
console.log(copy.show === post.show);
console.log(copy.when instanceof Date, JSON.stringify(copy.when));
